INSERT INTO `articles` (`id`, `category_id`, `author_id`, `title`, `slug`, `summary`, `content`, `image`, `views`, `status`, `created_at`, `updated_at`) VALUES
(3, 4, 1, 'Phim điện ảnh mới phá kỷ lục phòng vé', 'phim-i-n-nh-m-i-ph-k-l-c-ph-ng-v', 'Bộ phim chiếu rạp mới nhất vừa lập kỷ lục chưa từng có tại thị trường phim Việt.', '<p>Đạo diễn cùng dàn diễn viên đã bất ngờ chia sẻ về thành tích khủng này. Bộ phim thu hút hàng triệu khán giả ra rạp chỉ sau vỏn vẹn 3 ngày ra mắt, mang lại doanh thu hàng chục tỷ đồng.</p>', '1775102335_69cde97fa609f.png', 5, 'published', '2026-04-02 03:54:29', '2026-04-25 05:24:39'),
(8, 4, 1, 'Bài hát đạt 400tr lượt xem', 'b-i-h-t-t-400tr-l-t-xem', 'Nơi này có anh của Sơn Tùng M-TP', '<p data-path-to-node=\"6\">S&aacute;ng nay, cộng đồng fan h&acirc;m mộ Sky đ&atilde; vỡ &ograve;a hạnh ph&uacute;c khi MV <em data-path-to-node=\"6\" data-index-in-node=\"61\">Nơi N&agrave;y C&oacute; Anh</em> đạt con số <strong data-path-to-node=\"6\" data-index-in-node=\"87\">400.000.000 lượt xem</strong> tr&ecirc;n nền tảng YouTube. Đ&acirc;y l&agrave; sản phẩm &acirc;m nhạc tiếp theo của Sơn T&ugrave;ng M-TP chạm tới cột mốc đ&aacute;ng mơ ước n&agrave;y.</p>\r\n<p data-path-to-node=\"7\">Việc một MV ra mắt từ năm 2017 nhưng vẫn giữ được sức n&oacute;ng bền bỉ sau nhiều năm l&agrave; minh chứng r&otilde; n&eacute;t nhất cho sức h&uacute;t \"kh&ocirc;ng đối thủ\" của nam ca sĩ sinh năm 1994.</p>\r\n<p data-path-to-node=\"13\">Với th&agrave;nh t&iacute;ch n&agrave;y, Sơn T&ugrave;ng M-TP tiếp tục củng cố vị thế l&agrave; nghệ sĩ Việt Nam sở hữu nhiều MV tr&ecirc;n 100, 200 v&agrave; 400 triệu view nhất. Điều n&agrave;y kh&ocirc;ng chỉ khẳng định t&agrave;i năng thi&ecirc;n bẩm m&agrave; c&ograve;n cho thấy chiến lược &acirc;m nhạc b&agrave;i bản, vượt xa tầm v&oacute;c của một ng&ocirc;i sao giải tr&iacute; th&ocirc;ng thường.</p>\r\n<p data-path-to-node=\"14\">Hiện tại, c&aacute;c fan đang t&iacute;ch cực \"c&agrave;y view\" để đưa c&aacute;c sản phẩm kh&aacute;c của anh ch&agrave;ng sớm đạt được những cột mốc mới. Chắc chắn, h&agrave;nh tr&igrave;nh chinh phục những kỷ lục của Sơn T&ugrave;ng M-TP sẽ c&ograve;n k&eacute;o d&agrave;i v&agrave; mang lại nhiều bất ngờ hơn nữa cho bản đồ &acirc;m nhạc Việt Nam.</p>\r\n<p><iframe style=\"display: table; margin-left: auto; margin-right: auto; width: 607px; height: 357px;\" src=\"https://www.youtube.com/embed/FN7ALfpGxiI?si=jpui0fWV2wn3bqf4\" width=\"714\" height=\"403\" allowfullscreen=\"allowfullscreen\"></iframe></p>', '1776672991_69e5e0df973e8.png', 44, 'published', '2026-04-20 08:16:31', '2026-04-29 10:34:43'),
(9, 3, 1, 'Man City bức xúc vì phải đá 3 trận trong 7 ngày', 'man-city-b-c-x-c-v-ph-i-3-tr-n-trong-7-ng-y', 'Đội bóng của Pep Guardiola đối mặt lịch đấu dày đặc trong tháng 5, do không được ban tổ chức Ngoại hạng Anh chấp thuận đề nghị điều chỉnh.', '<p class=\"Normal\">Theo lịch mới được c&ocirc;ng bố,&nbsp;<a href=\"https://vnexpress.net/chu-de/manchester-city-115\" rel=\"dofollow\" data-itm-source=\"#vn_source=Detail-TheThao_NgoaiHangAnh_TinTuc-5068065&amp;vn_campaign=Box-InternalLink&amp;vn_medium=Link-ManCity&amp;vn_term=Desktop&amp;vn_thumb=0\" data-itm-added=\"1\">Man City</a>&nbsp;sẽ tiếp Crystal Palace tr&ecirc;n s&acirc;n Etihad ng&agrave;y 13/5, rồi đ&aacute; chung kết Cup FA với Chelsea ng&agrave;y 16/5. Sau đ&oacute;, họ l&agrave;m kh&aacute;ch tr&ecirc;n s&acirc;n Vitality của Bournemouth (19/5) trước khi kh&eacute;p lại m&ugrave;a giải bằng trận gặp Aston Villa (24/5).</p>\r\n<p class=\"Normal\">Theo&nbsp;<em>ESPN</em>, ban l&atilde;nh đạo Man City kh&ocirc;ng h&agrave;i l&ograve;ng khi phải đối mặt với lịch thi đấu d&agrave;y đặc ở giai đoạn cuối m&ugrave;a. Đội b&oacute;ng đ&atilde; đưa ra nhiều phương &aacute;n với Ngoại hạng Anh nhưng kh&ocirc;ng đạt được thỏa thuận.</p>\r\n<p class=\"Normal\"><img src=\"https://i1-thethao.vnecdn.net/2026/04/29/pep-PNG-1777403160-8314-1777403228.png?w=680&amp;h=0&amp;q=100&amp;dpr=1&amp;fit=crop&amp;s=C2WqwYt02vb6AMktwOKShQ\" alt=\"HLV Pep Guardiola (tr&aacute;i) phản ứng trong trận Man City thắng Arsenal 2-1 ở v&ograve;ng 33 Ngoại hạng Anh, tr&ecirc;n s&acirc;n Etihad, Manchester, Anh ng&agrave;y 19/4/2026. Ảnh: AP\"></p>', '1777462172_69f1eb9c9b8b0.png', 1, 'published', '2026-04-29 10:51:30', '2026-04-29 11:29:32'),
(10, 10, 1, 'Giá vàng lùi về 166 triệu đồng trước nghỉ lễ', 'gi-v-ng-l-i-v-166-tri-u-ng-tr-c-ngh-l', 'Mỗi lượng vàng giảm 1,5 triệu đồng xuống thấp nhất một tháng theo đà thế giới, chênh lệch giữa hai thị trường neo quanh 20 triệu đồng.', '<p class=\"Normal\">S&aacute;ng 29/4, C&ocirc;ng ty V&agrave;ng bạc đ&aacute; qu&yacute; S&agrave;i G&ograve;n (SJC) ni&ecirc;m yết&nbsp;<a href=\"https://vnexpress.net/chu-de/gia-vang-1403\" rel=\"dofollow\" data-itm-source=\"#vn_source=Detail-KinhDoanh_HangHoa-5068231&amp;vn_campaign=Box-InternalLink&amp;vn_medium=Link-GiaVang&amp;vn_term=Desktop&amp;vn_thumb=0\" data-itm-added=\"1\">gi&aacute; v&agrave;ng</a>&nbsp;miếng tại 163 - 166 triệu đồng một lượng, giảm 1,5 triệu đồng mỗi lượng so với h&ocirc;m qua. C&aacute;c thương hiệu kh&aacute;c cũng điều chỉnh gi&aacute; v&agrave;ng miếng tương ứng.</p>\r\n<p class=\"Normal\">Nhẫn trơn tại SJC cũng giảm về 162,5 - 165,5 triệu đồng một lượng. Mi Hồng ni&ecirc;m yết nhẫn trơn tại 163,5 - 165,5 triệu đồng.</p>\r\n<p class=\"Normal\">Gi&aacute; v&agrave;ng đi xuống từ đầu th&aacute;ng 3 sau khi xung đột Mỹ - Iran nổ ra. Hiện, mỗi lượng v&agrave;ng thấp hơn 25 triệu đồng một lượng so với c&aacute;ch đ&acirc;y hai th&aacute;ng, tương đương mức giảm 13%. So với đầu năm, hiện gi&aacute; v&agrave;ng trong nước chỉ cao hơn 9 triệu đồng một lượng tương đương 5% so với đầu năm.</p>\r\n<p class=\"Normal\">Tr&ecirc;n thị trường bạc, gi&aacute; kim loại n&agrave;y cũng trong diễn biến ảm đạm. Gi&aacute; bạc thỏi trong nước s&aacute;ng nay neo quanh 2,8 - 2,89 triệu đồng một lượng, tương đương 74,5 - 76,9 triệu một kg.</p>\r\n<div class=\"embed-container\"><iframe src=\"https://flo.uri.sh/visualisation/28035322/embed\" width=\"100%\" height=\"500\" frameborder=\"0\" scrolling=\"no\" data-src=\"https://flo.uri.sh/visualisation/28035322/embed\"></iframe></div>\r\n<p>&nbsp;</p>\r\n<p class=\"Normal\">Gi&aacute; v&agrave;ng trong nước điều chỉnh theo diễn biến thế giới. Gi&aacute; v&agrave;ng thế giới giảm hơn 100 USD v&agrave; duy tr&igrave; dưới 4.600 USD một ounce. Quy đổi theo tỷ gi&aacute; b&aacute;n Vietcombank, hiện ch&ecirc;nh lệch gi&aacute; v&agrave;ng trong nước v&agrave; thế giới gần 20 triệu một lượng.</p>\r\n<p class=\"Normal\">Thị trường mới đ&acirc;y đi xuống do nỗi lo lạm ph&aacute;t k&eacute;o d&agrave;i, sau khi Tổng thống Mỹ Donald Trump dường như kh&ocirc;ng h&agrave;i l&ograve;ng với đề xuất mới nhất của Iran nhằm chấm dứt chiến sự. Nh&agrave; đầu tư cũng đang đợi kết quả phi&ecirc;n họp ch&iacute;nh s&aacute;ch tuần n&agrave;y của Cục Dự trữ li&ecirc;n bang Mỹ (Fed).</p>\r\n<p class=\"Normal\">Giữa th&aacute;ng 4, &ocirc;ng Đ&agrave;o Xu&acirc;n Tuấn, Vụ trưởng Quản l&yacute; ngoại hối (Ng&acirc;n h&agrave;ng Nh&agrave; nước) cho biết, việc x&eacute;t duyệt hồ sơ xin cấp ph&eacute;p sản xuất v&agrave;ng miếng được thực hiện chặt chẽ. Ng&acirc;n h&agrave;ng Nh&agrave; nước đang xem x&eacute;t v&agrave; sẽ c&ocirc;ng bố c&aacute;c đơn vị được đủ điều kiện được cấp ph&eacute;p sản xuất v&agrave;ng miếng.</p>\r\n<p class=\"Normal\">Theo &ocirc;ng Tuấn, việc bổ sung th&ecirc;m c&aacute;c đơn vị được cấp ph&eacute;p sản xuất v&agrave;ng miếng sẽ gi&uacute;p tăng nguồn cung, g&oacute;p phần b&igrave;nh ổn thị trường v&agrave; thu hẹp ch&ecirc;nh lệch gi&aacute; v&agrave;ng trong nước với thế giới.</p>', '1777462132_69f1eb74b89c8.png', 1, 'published', '2026-04-29 10:55:43', '2026-04-29 11:28:52'),
(11, 8, 1, 'Uống rượu nhịn tiểu, chàng trai ngã vỡ bàng quang', 'u-ng-r-u-nh-n-ti-u-ch-ng-trai-ng-v-b-ng-quang', 'Sau khi uống rượu bia, nam thanh niên 29 tuổi vấp ngã sau đó đau tức bụng, đi tiểu ra máu, bác sĩ chẩn đoán vỡ bàng quang.', '<p class=\"Normal\">B&aacute;c sĩ Bệnh viện Đa khoa khu vực S&ocirc;ng M&atilde; đặt sonde b&agrave;ng quang cho bệnh nh&acirc;n rồi chuyển đến Bệnh viện Đa khoa tỉnh Sơn La điều trị. H&igrave;nh ảnh chụp cắt lớp vi t&iacute;nh cho thấy b&agrave;ng quang vỡ, trong ổ bụng bệnh nh&acirc;n c&oacute; nhiều dịch v&agrave; m&aacute;u cục.</p>\r\n<p class=\"Normal\">Ng&agrave;y 29/4, b&aacute;c sĩ Nguyễn Văn Trọng, Trưởng khoa Ngoại Tiết niệu - Nam học, cho biết bệnh nh&acirc;n bị chấn thương bụng k&iacute;n vỡ b&agrave;ng quang, được phẫu thuật cắt lọc m&eacute;p vết vỡ v&agrave; kh&acirc;u phục hồi b&agrave;ng quang hai lớp.</p>\r\n<p class=\"Normal\">Sau phẫu thuật, bệnh nh&acirc;n hồi phục tốt, sức khỏe ổn định v&agrave; c&oacute; thể đi tiểu b&igrave;nh thường trở lại. Anh cho hay đ&atilde; nhịn đi tiểu trong uống chầu nhậu. B&aacute;c sĩ nhận định c&oacute; thể b&agrave;ng quang bệnh nh&acirc;n đầy nước tiểu dẫn đến vỡ khi anh ng&atilde;.</p>\r\n<figure class=\"tplCaption action_thumb_added\" data-size=\"true\">\r\n<div class=\"fig-picture el_valid\" data-width=\"680\" data-src=\"https://i1-suckhoe.vnecdn.net/2026/04/29/680326728-1386587410162687-712-5058-1185-1777426044.jpg?w=0&amp;h=0&amp;q=100&amp;dpr=2&amp;fit=crop&amp;s=cRK1PwgSIDvatdsormZBBA\" data-sub-html=\"&lt;div class=&quot;ss-wrapper&quot;&gt;&lt;div class=&quot;ss-content&quot;&gt;\r\n&lt;p class=&quot;Image&quot;&gt;B&aacute;c sĩ theo d&otilde;i sức khỏe bệnh nh&acirc;n sau phẫu thuật. Ảnh: &lt;em&gt;Bệnh viện cung cấp&lt;/em&gt;&lt;/p&gt;\r\n&lt;/div&gt;&lt;/div&gt;\"><picture><source srcset=\"https://i1-suckhoe.vnecdn.net/2026/04/29/680326728-1386587410162687-712-5058-1185-1777426044.jpg?w=680&amp;h=0&amp;q=100&amp;dpr=1&amp;fit=crop&amp;s=TPl00Vl4ngF3JYLaWssjjA 1x, https://i1-suckhoe.vnecdn.net/2026/04/29/680326728-1386587410162687-712-5058-1185-1777426044.jpg?w=1020&amp;h=0&amp;q=100&amp;dpr=1&amp;fit=crop&amp;s=vWURZjchCRD0ldM75O7loQ 1.5x, https://i1-suckhoe.vnecdn.net/2026/04/29/680326728-1386587410162687-712-5058-1185-1777426044.jpg?w=680&amp;h=0&amp;q=100&amp;dpr=2&amp;fit=crop&amp;s=DWA4yxXe3TDuokq1Kp0EIg 2x\" data-srcset=\"https://i1-suckhoe.vnecdn.net/2026/04/29/680326728-1386587410162687-712-5058-1185-1777426044.jpg?w=680&amp;h=0&amp;q=100&amp;dpr=1&amp;fit=crop&amp;s=TPl00Vl4ngF3JYLaWssjjA 1x, https://i1-suckhoe.vnecdn.net/2026/04/29/680326728-1386587410162687-712-5058-1185-1777426044.jpg?w=1020&amp;h=0&amp;q=100&amp;dpr=1&amp;fit=crop&amp;s=vWURZjchCRD0ldM75O7loQ 1.5x, https://i1-suckhoe.vnecdn.net/2026/04/29/680326728-1386587410162687-712-5058-1185-1777426044.jpg?w=680&amp;h=0&amp;q=100&amp;dpr=2&amp;fit=crop&amp;s=DWA4yxXe3TDuokq1Kp0EIg 2x\"><img class=\"lazy lazied\" src=\"https://i1-suckhoe.vnecdn.net/2026/04/29/680326728-1386587410162687-712-5058-1185-1777426044.jpg?w=680&amp;h=0&amp;q=100&amp;dpr=1&amp;fit=crop&amp;s=TPl00Vl4ngF3JYLaWssjjA\" alt=\"B&aacute;c sĩ theo d&otilde;i sức khỏe bệnh nh&acirc;n sau phẫu thuật. Ảnh: Bệnh viện cung cấp\" width=\"461\" height=\"307\" loading=\"lazy\" data-src=\"https://i1-suckhoe.vnecdn.net/2026/04/29/680326728-1386587410162687-712-5058-1185-1777426044.jpg?w=680&amp;h=0&amp;q=100&amp;dpr=1&amp;fit=crop&amp;s=TPl00Vl4ngF3JYLaWssjjA\" data-ll-status=\"loaded\"></picture></div>\r\n<figcaption>\r\n<p class=\"Image\">B&aacute;c sĩ theo d&otilde;i sức khỏe bệnh nh&acirc;n sau phẫu thuật. Ảnh:&nbsp;<em>Bệnh viện cung cấp</em></p>\r\n</figcaption>\r\n</figure>\r\n<p class=\"Normal\">Vỡ b&agrave;ng quang l&agrave; cấp cứu ngoại khoa nguy hiểm v&agrave; thường gặp, c&oacute; thể g&acirc;y vi&ecirc;m ph&uacute;c mạc nước tiểu, nhiễm tr&ugrave;ng - nhiễm độc v&agrave; diễn biến nặng nếu chậm trễ xử tr&iacute;. Phần lớn nguy&ecirc;n nh&acirc;n do say rượu hoặc tai nạn giao th&ocirc;ng ng&atilde; khi người bệnh uống nhiều bia rượu, b&agrave;ng quang căng đầy do nhịn tiểu.</p>\r\n<p class=\"Normal\">\"Th&agrave;nh b&agrave;ng quang rất mỏng, khi chứa đầy nước tiểu, nếu chấn thương sức &eacute;p b&ecirc;n trong bị tăng cao đột ngột, chỉ cần một lực t&aacute;c động nhẹ cũng dẫn đến vỡ b&agrave;ng quang\", b&aacute;c sĩ giải th&iacute;ch.</p>\r\n<p class=\"Normal\">B&aacute;c sĩ khuyến c&aacute;o nhịn tiểu l&agrave; một th&oacute;i quen kh&ocirc;ng tốt cho sức khỏe. Về l&acirc;u d&agrave;i, nhịn tiểu c&oacute; thể dẫn đến rối loạn tiểu tiện, vi&ecirc;m nhiễm hệ tiết niệu, sỏi thận, suy thận... Do vậy, tuyệt đối kh&ocirc;ng n&ecirc;n nhịn tiểu, nhất l&agrave; sau khi uống nhiều rượu bia. Trường hợp sau khi ng&atilde; bị đau bụng dưới, b&iacute; tiểu hay tiểu ra m&aacute;u, phải đến ngay bệnh viện để điều trị kịp thời.</p>', '1777462230_69f1ebd6f0751.png', 1, 'published', '2026-04-29 10:59:39', '2026-04-29 11:30:30'),
(12, 11, 1, 'Ông Trump đáp trả Thủ tướng Đức sau bình luận \'Iran làm cho Mỹ bẽ mặt\'', 'ng-trump-p-tr-th-t-ng-c-sau-b-nh-lu-n-iran-l-m-cho-m-b-m-t', 'Tổng thống Trump công kích Thủ tướng Merz sau khi lãnh đạo Đức nói Mỹ không có chiến lược rõ ràng và đang bị Iran \"làm cho bẽ mặt\".', '<p class=\"Normal\">\"Thủ tướng Đức Friedrich Merz nghĩ rằng Iran sở hữu vũ kh&iacute; hạt nh&acirc;n cũng chẳng sao. &Ocirc;ng ấy kh&ocirc;ng hiểu m&igrave;nh đang n&oacute;i g&igrave;. Nếu Iran c&oacute; vũ kh&iacute; hạt nh&acirc;n, cả thế giới sẽ bị bắt l&agrave;m con tin. Những việc t&ocirc;i đang l&agrave;m với Iran l&agrave; điều đ&aacute;ng lẽ c&aacute;c nước v&agrave; những đời tổng thống trước đ&acirc;y phải cố gắng thực hiện từ l&acirc;u rồi\", Tổng thống Mỹ Donald Trump ng&agrave;y 28/4 viết tr&ecirc;n Truth Social.</p>\r\n<p class=\"Normal\">&Ocirc;ng đồng thời c&ocirc;ng k&iacute;ch ch&iacute;nh phủ Đức, cho rằng Berlin đang \"l&agrave;m rất tệ cả về kinh tế lẫn những phương diện kh&aacute;c\".</p>\r\n<p class=\"Normal\">Ph&aacute;t biểu trong một sự kiện đối thoại sinh vi&ecirc;n ở Đức một ng&agrave;y trước đ&oacute;, Thủ tướng Merz cho rằng Mỹ \"r&otilde; r&agrave;ng kh&ocirc;ng c&oacute; kế hoạch chiến lược\" trong c&aacute;ch xử l&yacute; xung đột với Iran. &Ocirc;ng ph&acirc;n t&iacute;ch rằng th&aacute;ch thức trong c&aacute;c xung đột với c&aacute;c ch&iacute;nh phủ kh&ocirc;ng chỉ l&agrave; c&acirc;u chuyện tham gia m&agrave; c&ograve;n phải t&iacute;nh được đường r&uacute;t lui, dẫn chứng c&aacute;c b&agrave;i học tại Afghanistan v&agrave; Iraq.</p>\r\n<figure class=\"tplCaption action_thumb_added\" data-size=\"true\">\r\n<div class=\"fig-picture el_valid\" data-width=\"680\" data-src=\"https://i1-vnexpress.vnecdn.net/2026/04/29/Trump-Merz-4013-1777452345.jpg?w=0&amp;h=0&amp;q=100&amp;dpr=2&amp;fit=crop&amp;s=3Fza4MlhE_RgkdCeBV732w\" data-sub-html=\"&lt;div class=&quot;ss-wrapper&quot;&gt;&lt;div class=&quot;ss-content&quot;&gt;\r\n&lt;p class=&quot;Image&quot;&gt;Tổng thống Mỹ Donald Trump (phải) v&agrave; Thủ tướng Đức Friedrich Merz tại Nh&agrave; Trắng ng&agrave;y 3/3. Ảnh: &lt;em&gt;AFP&lt;/em&gt;&lt;/p&gt;\r\n&lt;/div&gt;&lt;/div&gt;\"><picture><source srcset=\"https://i1-vnexpress.vnecdn.net/2026/04/29/Trump-Merz-4013-1777452345.jpg?w=680&amp;h=0&amp;q=100&amp;dpr=1&amp;fit=crop&amp;s=3_d_om9Gjlb758A57TYgzQ 1x, https://i1-vnexpress.vnecdn.net/2026/04/29/Trump-Merz-4013-1777452345.jpg?w=1020&amp;h=0&amp;q=100&amp;dpr=1&amp;fit=crop&amp;s=dzoA9tD61X_9pObPjaVo1A 1.5x, https://i1-vnexpress.vnecdn.net/2026/04/29/Trump-Merz-4013-1777452345.jpg?w=680&amp;h=0&amp;q=100&amp;dpr=2&amp;fit=crop&amp;s=-USXHJasIE74x7JDUIU5Eg 2x\" data-srcset=\"https://i1-vnexpress.vnecdn.net/2026/04/29/Trump-Merz-4013-1777452345.jpg?w=680&amp;h=0&amp;q=100&amp;dpr=1&amp;fit=crop&amp;s=3_d_om9Gjlb758A57TYgzQ 1x, https://i1-vnexpress.vnecdn.net/2026/04/29/Trump-Merz-4013-1777452345.jpg?w=1020&amp;h=0&amp;q=100&amp;dpr=1&amp;fit=crop&amp;s=dzoA9tD61X_9pObPjaVo1A 1.5x, https://i1-vnexpress.vnecdn.net/2026/04/29/Trump-Merz-4013-1777452345.jpg?w=680&amp;h=0&amp;q=100&amp;dpr=2&amp;fit=crop&amp;s=-USXHJasIE74x7JDUIU5Eg 2x\"><img class=\"lazy lazied\" src=\"https://i1-vnexpress.vnecdn.net/2026/04/29/Trump-Merz-4013-1777452345.jpg?w=680&amp;h=0&amp;q=100&amp;dpr=1&amp;fit=crop&amp;s=3_d_om9Gjlb758A57TYgzQ\" alt=\"Tổng thống Mỹ Donald Trump (phải) v&agrave; Thủ tướng Đức Friedrich Merz tại Nh&agrave; Trắng ng&agrave;y 3/3. Ảnh: AFP\" loading=\"lazy\" data-src=\"https://i1-vnexpress.vnecdn.net/2026/04/29/Trump-Merz-4013-1777452345.jpg?w=680&amp;h=0&amp;q=100&amp;dpr=1&amp;fit=crop&amp;s=3_d_om9Gjlb758A57TYgzQ\" data-ll-status=\"loaded\"></picture></div>\r\n<figcaption>\r\n<p class=\"Image\" style=\"text-align: center;\"><em><span style=\"font-size: 10pt;\">Tổng thống Mỹ Donald Trump (phải) v&agrave; Thủ tướng Đức Friedrich Merz tại Nh&agrave; Trắng ng&agrave;y 3/3. Ảnh:&nbsp;AFP</span></em></p>\r\n</figcaption>\r\n</figure>\r\n<p class=\"Normal\">&Ocirc;ng nhận định Tehran đang thể hiện kỹ năng đ&agrave;m ph&aacute;n hiệu quả để tạo ra lợi thế trước Mỹ. \"N&oacute;i ch&iacute;nh x&aacute;c hơn, người Iran đang kh&eacute;o l&eacute;o chọn kh&ocirc;ng đ&agrave;m ph&aacute;n. Họ để cho ph&aacute;i đo&agrave;n Mỹ đến tận Islamabad, để rồi trở về m&agrave; kh&ocirc;ng đạt được bất kỳ th&agrave;nh quả n&agrave;o. Cả một đất nước bị l&agrave;m cho bẽ mặt bởi giới l&atilde;nh đạo Iran, cụ thể l&agrave; lực lượng Vệ binh C&aacute;ch mạng Hồi gi&aacute;o\", &ocirc;ng Merz n&oacute;i.</p>\r\n<p class=\"Normal\">Những ph&aacute;t biểu của l&atilde;nh đạo Đức được đưa ra giữa giai đoạn nỗ lực đối thoại giữa Mỹ v&agrave; Iran chưa đạt tiến triển đ&aacute;ng kể. V&ograve;ng tiếp x&uacute;c đầu ti&ecirc;n tại Islamabad kết th&uacute;c m&agrave; kh&ocirc;ng c&oacute; kết quả, trong khi kế hoạch cử đặc ph&aacute;i vi&ecirc;n tới Pakistan thương lượng v&ograve;ng hai đ&atilde; bị hủy v&agrave;o ph&uacute;t ch&oacute;t.</p>\r\n<p class=\"Normal\">Tổng thống Trump cho biết Iran đ&atilde; gửi một đề xuất m&agrave; &ocirc;ng cho l&agrave; chưa đạt y&ecirc;u cầu, song sau khi Mỹ hủy chuyến đi của ph&aacute;i đo&agrave;n đ&agrave;m ph&aacute;n, ph&iacute;a Tehran đ&atilde; đưa ra một đề xuất mới tốt hơn. &Ocirc;ng cũng viết rằng Iran n&oacute;i với Mỹ họ&nbsp;<a href=\"https://vnexpress.net/ong-trump-iran-noi-dang-tren-bo-vuc-sup-do-5068054.html\" rel=\"dofollow\" data-itm-source=\"#vn_source=Detail-TheGioi-5068387&amp;vn_campaign=Box-InternalLink&amp;vn_medium=Link-TrenBoVucSupDo&amp;vn_term=Desktop&amp;vn_thumb=0\" data-itm-added=\"1\">\"tr&ecirc;n bờ vực sụp đổ\"</a>&nbsp;v&agrave; mong muốn Washington chấm dứt lệnh phong tỏa với cảng biển.</p>\r\n<p class=\"Normal\">Trong b&agrave;i đăng tr&ecirc;n Truth Social h&ocirc;m nay, &ocirc;ng Trump ph&agrave;n n&agrave;n Iran đang \"kh&ocirc;ng thể tự lo liệu ổn thỏa\", cảnh b&aacute;o nước n&agrave;y \"tốt nhất n&ecirc;n sớm kh&ocirc;n ngoan l&ecirc;n\". \"Họ kh&ocirc;ng biết c&aacute;ch k&yacute; một thỏa thuận phi hạt nh&acirc;n,\" &ocirc;ng viết th&ecirc;m.</p>\r\n<p class=\"Normal\">Tổng thống Mỹ nhiều lần b&agrave;y tỏ kh&ocirc;ng h&agrave;i l&ograve;ng với c&aacute;c đồng minh ch&acirc;u &Acirc;u, trong đ&oacute; c&oacute; Đức, v&igrave; từ chối tham gia s&acirc;u hơn v&agrave;o chiến dịch chống lại Iran.</p>\r\n<p class=\"Normal\">Giới l&atilde;nh đạo Đức đ&atilde; khẳng định kh&ocirc;ng c&oacute; &yacute; định can dự xung đột giữa Mỹ - Israel với Iran. C&aacute;c nước ch&acirc;u &Acirc;u cũng tuy&ecirc;n bố chỉ tham gia bảo vệ t&agrave;u thuyền di chuyển qua eo biển Hormuz một khi xung đột chấm dứt ho&agrave;n to&agrave;n.</p>\r\n<p class=\"Normal\" style=\"padding-left: 40px; text-align: right;\"><strong>Thanh Danh&nbsp;</strong>(Theo&nbsp;<em>Hill, Al Jazeera, Guardian</em>)</p>', '1777462154_69f1eb8a171cd.png', 2, 'published', '2026-04-29 11:03:54', '2026-04-29 11:29:14'),
(13, 2, 1, '900.000 số điện thoại bị xác nhận \'không chính chủ\'', '900-000-s-i-n-tho-i-b-x-c-nh-n-kh-ng-ch-nh-ch', 'Khoảng 900.000 số điện thoại đã được xác nhận không chính chủ sau hai tuần triển khai Thông tư 08 về xác thực thông tin thuê bao di động.', '<p class=\"description\">Khoảng 900.000 số điện thoại đ&atilde; được x&aacute;c nhận kh&ocirc;ng ch&iacute;nh chủ sau hai tuần triển khai Th&ocirc;ng tư 08 về x&aacute;c thực th&ocirc;ng tin thu&ecirc; bao di động.</p>\r\n<article id=\"fck_detail_gallery\" class=\"fck_detail \">\r\n<p class=\"Normal\">Th&ocirc;ng tư 08 lần đầu cho ph&eacute;p người d&ugrave;ng chủ động x&aacute;c nhận SIM ch&iacute;nh chủ th&ocirc;ng qua ứng dụng VNeID, đồng thời loại bỏ số kh&ocirc;ng c&ograve;n sử dụng hoặc số điện thoại lạ.</p>\r\n<p class=\"Normal\">Tại họp b&aacute;o thường kỳ th&aacute;ng 4 của Bộ Khoa học v&agrave; C&ocirc;ng nghệ, chiều 29/4, &ocirc;ng Nguyễn Anh Cương, Ph&oacute; cục trưởng Viễn th&ocirc;ng, dẫn số liệu sơ bộ từ Cục Cảnh s&aacute;t Quản l&yacute; h&agrave;nh ch&iacute;nh về trật tự x&atilde; hội (C06, Bộ C&ocirc;ng an) cho thấy hơn 95 triệu thu&ecirc; bao di động đ&atilde; được đồng bộ l&ecirc;n hệ thống, trong đ&oacute; 60 triệu \"được x&aacute;c nhận ch&iacute;nh chủ\".</p>\r\n<p class=\"Normal\">Trong khi đ&oacute;, gần 900.000 thu&ecirc; bao được người d&ugrave;ng chủ động x&aacute;c nhận \"kh&ocirc;ng ch&iacute;nh chủ\" th&ocirc;ng qua VNeID. \"Qu&aacute; tr&igrave;nh n&agrave;y sẽ tiếp tục được triển khai đến ng&agrave;y 15/6\", &ocirc;ng Cương n&oacute;i.</p>\r\n<figure class=\"tplCaption action_thumb_added\" data-size=\"true\">\r\n<div class=\"fig-picture el_valid\" data-width=\"680\" data-src=\"https://i1-vnexpress.vnecdn.net/2026/04/29/DSC-3909-JPG-4480-1777449738.jpg?w=0&amp;h=0&amp;q=100&amp;dpr=2&amp;fit=crop&amp;s=E1FSZF-rluz2MVm2rzyoIg\" data-sub-html=\"&lt;div class=&quot;ss-wrapper&quot;&gt;&lt;div class=&quot;ss-content&quot;&gt;\r\n&lt;p class=&quot;Image&quot;&gt;&Ocirc;ng Nguyễn Anh Cương, Ph&oacute; cục trưởng Viễn th&ocirc;ng, chia sẻ tại họp b&aacute;o thường kỳ th&aacute;ng 4 của Bộ Khoa học v&agrave; C&ocirc;ng nghệ, chiều 29/4. Ảnh: &lt;em&gt;Trọng Đạt&lt;/em&gt;&lt;/p&gt;\r\n&lt;/div&gt;&lt;/div&gt;\"><picture><source srcset=\"https://i1-vnexpress.vnecdn.net/2026/04/29/DSC-3909-JPG-4480-1777449738.jpg?w=680&amp;h=0&amp;q=100&amp;dpr=1&amp;fit=crop&amp;s=ZgNrlBrPc3FaaXNk4n4mdw 1x, https://i1-vnexpress.vnecdn.net/2026/04/29/DSC-3909-JPG-4480-1777449738.jpg?w=1020&amp;h=0&amp;q=100&amp;dpr=1&amp;fit=crop&amp;s=wtHYvMJfCdd7z280GgzAtQ 1.5x, https://i1-vnexpress.vnecdn.net/2026/04/29/DSC-3909-JPG-4480-1777449738.jpg?w=680&amp;h=0&amp;q=100&amp;dpr=2&amp;fit=crop&amp;s=1BPgbx9iG5rSjEajVvM1-Q 2x\" data-srcset=\"https://i1-vnexpress.vnecdn.net/2026/04/29/DSC-3909-JPG-4480-1777449738.jpg?w=680&amp;h=0&amp;q=100&amp;dpr=1&amp;fit=crop&amp;s=ZgNrlBrPc3FaaXNk4n4mdw 1x, https://i1-vnexpress.vnecdn.net/2026/04/29/DSC-3909-JPG-4480-1777449738.jpg?w=1020&amp;h=0&amp;q=100&amp;dpr=1&amp;fit=crop&amp;s=wtHYvMJfCdd7z280GgzAtQ 1.5x, https://i1-vnexpress.vnecdn.net/2026/04/29/DSC-3909-JPG-4480-1777449738.jpg?w=680&amp;h=0&amp;q=100&amp;dpr=2&amp;fit=crop&amp;s=1BPgbx9iG5rSjEajVvM1-Q 2x\"><img class=\"lazy lazied\" src=\"https://i1-vnexpress.vnecdn.net/2026/04/29/DSC-3909-JPG-4480-1777449738.jpg?w=680&amp;h=0&amp;q=100&amp;dpr=1&amp;fit=crop&amp;s=ZgNrlBrPc3FaaXNk4n4mdw\" alt=\"&Ocirc;ng Nguyễn Anh Cương, Ph&oacute; cục trưởng Viễn th&ocirc;ng chia sẻ tại họp b&aacute;o thường kỳ th&aacute;ng 4 của Bộ Khoa học v&agrave; C&ocirc;ng nghệ, chiều 29/4. Ảnh: Trọng Đạt\" loading=\"lazy\" data-src=\"https://i1-vnexpress.vnecdn.net/2026/04/29/DSC-3909-JPG-4480-1777449738.jpg?w=680&amp;h=0&amp;q=100&amp;dpr=1&amp;fit=crop&amp;s=ZgNrlBrPc3FaaXNk4n4mdw\" data-ll-status=\"loaded\"></picture></div>\r\n<figcaption>\r\n<p class=\"Image\">&Ocirc;ng Nguyễn Anh Cương, Ph&oacute; cục trưởng Viễn th&ocirc;ng, chia sẻ tại họp b&aacute;o thường kỳ th&aacute;ng 4 của Bộ Khoa học v&agrave; C&ocirc;ng nghệ, chiều 29/4. Ảnh:&nbsp;<em>Trọng Đạt</em></p>\r\n</figcaption>\r\n</figure>\r\n<p class=\"Normal\">Đại diện Cục Viễn th&ocirc;ng nhấn mạnh, việc x&aacute;c nhận SIM ch&iacute;nh chủ l&agrave; bước tiếp theo sau giai đoạn \"l&agrave;m sạch dữ liệu\" năm 2023. Khi đ&oacute;, cơ quan quản l&yacute; đ&atilde; đối so&aacute;t th&ocirc;ng tin giấy tờ của cả trăm triệu thu&ecirc; bao di động, qua đ&oacute; ph&aacute;t hiện khoảng 17 triệu trường hợp c&oacute; th&ocirc;ng tin chưa ch&iacute;nh x&aacute;c. Trong số n&agrave;y, 11 triệu thu&ecirc; bao đ&atilde; được cập nhật lại th&ocirc;ng tin, c&ograve;n 6 triệu bị dừng cung cấp dịch vụ.</p>\r\n<p class=\"Normal\">\"So với giai đoạn trước, c&aacute;ch l&agrave;m hiện nay c&oacute; sự thay đổi\", &ocirc;ng Cương giải th&iacute;ch, th&ecirc;m rằng trọng t&acirc;m hiện nay l&agrave; trao cho người d&acirc;n quyền chủ động kiểm tra v&agrave; x&aacute;c nhận th&ocirc;ng tin thu&ecirc; bao đang sử dụng.</p>\r\n<p class=\"Normal\">Theo đại diện cơ quan quản l&yacute;, mục ti&ecirc;u của Th&ocirc;ng tư 08 l&agrave; x&acirc;y dựng cơ sở dữ liệu thu&ecirc; bao \"sạch\", minh bạch, qua đ&oacute; bảo vệ quyền lợi người d&ugrave;ng v&agrave; g&oacute;p phần ph&ograve;ng chống c&aacute;c h&agrave;nh vi lừa đảo, vi phạm ph&aacute;p luật li&ecirc;n quan đến SIM điện thoại.</p>\r\n<p class=\"Normal\">Th&ocirc;ng tư 08, do Bộ Khoa học v&agrave; C&ocirc;ng nghệ ban h&agrave;nh ng&agrave;y 31/3, nhằm siết quản l&yacute; SIM kh&ocirc;ng ch&iacute;nh chủ. Th&ocirc;ng tư c&oacute; hai điểm mới đ&aacute;ng ch&uacute; &yacute;: cho ph&eacute;p người d&ugrave;ng chủ động x&aacute;c nhận số điện thoại đang sử dụng th&ocirc;ng qua ứng dụng VNeID (từ 15/4); v&agrave; y&ecirc;u cầu x&aacute;c thực lại khu&ocirc;n mặt khi thực hiện đổi SIM sang thiết bị mới (từ 15/6).</p>\r\n<figure class=\"tplCaption action_thumb_added\" data-size=\"true\">\r\n<div class=\"fig-picture el_valid\" data-width=\"680\" data-src=\"https://i1-vnexpress.vnecdn.net/2026/04/29/SIM-5425-1777449741.jpg?w=0&amp;h=0&amp;q=100&amp;dpr=2&amp;fit=crop&amp;s=jU0DK1h_3vdgr1cm0yfPdw\" data-sub-html=\"&lt;div class=&quot;ss-wrapper&quot;&gt;&lt;div class=&quot;ss-content&quot;&gt;\r\n&lt;p class=&quot;Image&quot;&gt;Hai thẻ SIM di động. Ảnh: &lt;em&gt;Trọng Đạt&lt;/em&gt;&lt;/p&gt;\r\n&lt;/div&gt;&lt;/div&gt;\"><picture><source srcset=\"https://i1-vnexpress.vnecdn.net/2026/04/29/SIM-5425-1777449741.jpg?w=680&amp;h=0&amp;q=100&amp;dpr=1&amp;fit=crop&amp;s=MJlZIQgYhsjiFe8EmLg5fw 1x, https://i1-vnexpress.vnecdn.net/2026/04/29/SIM-5425-1777449741.jpg?w=1020&amp;h=0&amp;q=100&amp;dpr=1&amp;fit=crop&amp;s=XIqKbbDTR96ob2sc4FLMgA 1.5x, https://i1-vnexpress.vnecdn.net/2026/04/29/SIM-5425-1777449741.jpg?w=680&amp;h=0&amp;q=100&amp;dpr=2&amp;fit=crop&amp;s=i2cNnjN6hRhABxVIAb0vIA 2x\" data-srcset=\"https://i1-vnexpress.vnecdn.net/2026/04/29/SIM-5425-1777449741.jpg?w=680&amp;h=0&amp;q=100&amp;dpr=1&amp;fit=crop&amp;s=MJlZIQgYhsjiFe8EmLg5fw 1x, https://i1-vnexpress.vnecdn.net/2026/04/29/SIM-5425-1777449741.jpg?w=1020&amp;h=0&amp;q=100&amp;dpr=1&amp;fit=crop&amp;s=XIqKbbDTR96ob2sc4FLMgA 1.5x, https://i1-vnexpress.vnecdn.net/2026/04/29/SIM-5425-1777449741.jpg?w=680&amp;h=0&amp;q=100&amp;dpr=2&amp;fit=crop&amp;s=i2cNnjN6hRhABxVIAb0vIA 2x\"></picture></div>\r\n</figure>\r\n</article>', '1777462187_69f1ebab43e9e.png', 3, 'published', '2026-04-29 11:07:16', '2026-04-29 11:29:47'),
(14, 12, 1, 'Vì sao hang có hố sụt hiếm ở Quảng Trị không dành cho khách du lịch?', 'v-sao-hang-c-h-s-t-hi-m-qu-ng-tr-kh-ng-d-nh-cho-kh-ch-du-l-ch', 'Trưởng đoàn thám hiểm Howard Limbert cho biết quá trình tiếp cận lòng hang Chả Nghéo đòi hỏi kỹ thuật đi dây cực kỳ phức tạp, thường xuyên có đá mẻ rơi tự do từ vách hố sụt sâu 350 m.', '<p class=\"description\">Trưởng đo&agrave;n th&aacute;m hiểm Howard Limbert cho biết qu&aacute; tr&igrave;nh tiếp cận l&ograve;ng hang Chả Ngh&eacute;o đ&ograve;i hỏi kỹ thuật đi d&acirc;y cực kỳ phức tạp, thường xuy&ecirc;n c&oacute; đ&aacute; mẻ rơi tự do từ v&aacute;ch hố sụt s&acirc;u 350 m.</p>\r\n<article id=\"fck_detail_gallery\" class=\"fck_detail \">\r\n<p class=\"Normal\">Đợt khảo s&aacute;t hang động th&aacute;ng 4 của Hiệp hội Hang động Ho&agrave;ng gia Anh (BCRA) đ&atilde; c&ocirc;ng bố ph&aacute;t hiện 26 hang động mới tại tỉnh Quảng Trị. Trong đ&oacute;, hang Chả Ngh&eacute;o trở th&agrave;nh t&acirc;m điểm ch&uacute; &yacute; nhờ cấu tr&uacute;c th&aacute;c nước đổ thẳng v&agrave;o l&ograve;ng vực s&acirc;u. Tuy nhi&ecirc;n, đằng sau sự kỳ vĩ l&agrave; những giới hạn nghi&ecirc;m ngặt về t&iacute;nh an to&agrave;n.</p>\r\n<p class=\"Normal\">Theo th&ocirc;ng số khảo s&aacute;t của đo&agrave;n BCRA, hang Chả Ngh&eacute;o sở hữu một hố sụt thẳng đứng (vertical shaft) s&acirc;u 350 m, kết nối với một đoạn hang ngang d&agrave;i 600 m ở dưới đ&aacute;y. Đ&acirc;y l&agrave; hố sụt thẳng đứng đơn lẻ s&acirc;u nhất m&agrave; đo&agrave;n từng ghi nhận tại Việt Nam sau hơn 36 năm th&aacute;m hiểm. Cấu tr&uacute;c n&agrave;y kh&aacute;c biệt ho&agrave;n to&agrave;n với c&aacute;c hang ngang ổn định thường thấy tại khu vực n&agrave;y như Sơn Đo&ograve;ng hay hang &Eacute;n.</p>\r\n<figure class=\"tplCaption action_thumb_added\" data-size=\"true\">\r\n<div class=\"fig-picture el_valid\" data-width=\"680\" data-src=\"https://i1-dulich.vnecdn.net/2026/04/27/hang-cha-nghe-o-1777269510-9150-1777269597.jpg?w=0&amp;h=0&amp;q=100&amp;dpr=2&amp;fit=crop&amp;s=_tGwagsZlQVGnjwbbt4o3A\" data-sub-html=\"&lt;div class=&quot;ss-wrapper&quot;&gt;&lt;div class=&quot;ss-content&quot;&gt;\r\n&lt;p class=&quot;Image&quot;&gt;Chuy&ecirc;n gia đu d&acirc;y xuống hang Chả Ngh&eacute;o. Ảnh: &lt;em&gt;Oxalis&lt;/em&gt;&lt;/p&gt;\r\n&lt;/div&gt;&lt;/div&gt;\"><picture><source srcset=\"https://i1-dulich.vnecdn.net/2026/04/27/hang-cha-nghe-o-1777269510-9150-1777269597.jpg?w=680&amp;h=0&amp;q=100&amp;dpr=1&amp;fit=crop&amp;s=HSWgYZr242_eXHmgoByKYw 1x, https://i1-dulich.vnecdn.net/2026/04/27/hang-cha-nghe-o-1777269510-9150-1777269597.jpg?w=1020&amp;h=0&amp;q=100&amp;dpr=1&amp;fit=crop&amp;s=2rOU_4WKYc7TU2NquucDFA 1.5x, https://i1-dulich.vnecdn.net/2026/04/27/hang-cha-nghe-o-1777269510-9150-1777269597.jpg?w=680&amp;h=0&amp;q=100&amp;dpr=2&amp;fit=crop&amp;s=LB7W4ypt4hxJzfL35OtVqA 2x\" data-srcset=\"https://i1-dulich.vnecdn.net/2026/04/27/hang-cha-nghe-o-1777269510-9150-1777269597.jpg?w=680&amp;h=0&amp;q=100&amp;dpr=1&amp;fit=crop&amp;s=HSWgYZr242_eXHmgoByKYw 1x, https://i1-dulich.vnecdn.net/2026/04/27/hang-cha-nghe-o-1777269510-9150-1777269597.jpg?w=1020&amp;h=0&amp;q=100&amp;dpr=1&amp;fit=crop&amp;s=2rOU_4WKYc7TU2NquucDFA 1.5x, https://i1-dulich.vnecdn.net/2026/04/27/hang-cha-nghe-o-1777269510-9150-1777269597.jpg?w=680&amp;h=0&amp;q=100&amp;dpr=2&amp;fit=crop&amp;s=LB7W4ypt4hxJzfL35OtVqA 2x\"><img class=\"lazy lazied\" src=\"https://i1-dulich.vnecdn.net/2026/04/27/hang-cha-nghe-o-1777269510-9150-1777269597.jpg?w=680&amp;h=0&amp;q=100&amp;dpr=1&amp;fit=crop&amp;s=HSWgYZr242_eXHmgoByKYw\" alt=\"Chuy&ecirc;n gia đu d&acirc;y xuống hang Chảo Ngh&eacute;o. Ảnh: Oxalis\" loading=\"lazy\" data-src=\"https://i1-dulich.vnecdn.net/2026/04/27/hang-cha-nghe-o-1777269510-9150-1777269597.jpg?w=680&amp;h=0&amp;q=100&amp;dpr=1&amp;fit=crop&amp;s=HSWgYZr242_eXHmgoByKYw\" data-ll-status=\"loaded\"></picture></div>\r\n<figcaption>\r\n<p class=\"Image\" style=\"text-align: center;\">Chuy&ecirc;n gia đu d&acirc;y xuống hang Chả Ngh&eacute;o. Ảnh:&nbsp;<em>Oxalis</em></p>\r\n</figcaption>\r\n</figure>\r\n<p class=\"Normal\">&Ocirc;ng Howard Limbert, Trưởng đo&agrave;n th&aacute;m hiểm BCRA, đ&aacute;nh gi&aacute; độ s&acirc;u 350 m khiến hang Chả Ngh&eacute;o kh&oacute; tiếp cận, đ&ograve;i hỏi kỹ thuật đi d&acirc;y phức tạp v&agrave; ti&ecirc;u tốn nhiều sức lực hơn so với th&aacute;m hiểm c&aacute;c hang động nằm ngang. Nh&igrave;n từ dưới đ&aacute;y l&ecirc;n rất ấn tượng, nhưng kh&ocirc;ng c&oacute; c&aacute;ch n&agrave;o để xuống đ&oacute; được. Chỉ c&oacute; một v&agrave;i người tr&ecirc;n thế giới đủ khả năng xuống hang n&agrave;y an to&agrave;n. D&ugrave; đo&agrave;n c&oacute; 10 người d&agrave;y dạn kinh nghiệm, nhưng chỉ hai chuy&ecirc;n gia kỹ thuật tốt nhất được ph&eacute;p đu d&acirc;y xuống tiếp cận l&ograve;ng hang.</p>\r\n<p class=\"Normal\">\"Rất &iacute;t chuy&ecirc;n gia c&oacute; đủ kỹ năng để xuống v&agrave; leo l&ecirc;n an to&agrave;n, thậm ch&iacute; l&agrave; đi bộ đến cửa hang cũng kh&oacute; khăn, chắc chắn kh&ocirc;ng d&agrave;nh cho kh&aacute;ch du lịch\", &ocirc;ng Howard n&oacute;i.</p>\r\n<p class=\"Normal\">Anh Phạm Hồng Đại, chuy&ecirc;n gia an to&agrave;n của đo&agrave;n, cho biết th&ocirc;ng tin về hang Chả Ngh&eacute;o thực chất đ&atilde; được tiếp cận từ năm 2024 dựa tr&ecirc;n chỉ dẫn của người d&acirc;n địa phương. Để x&aacute;c định d&ograve;ng chảy, người d&acirc;n bản địa từng d&ugrave;ng phương ph&aacute;p d&acirc;n gian l&agrave; viết t&ecirc;n l&ecirc;n quả bưởi rồi n&eacute;m xuống hố sụt, nhưng kh&ocirc;ng t&igrave;m thấy dấu vết nổi l&ecirc;n của ch&uacute;ng.</p>\r\n<p class=\"Normal\">Ban đầu, hang được dự đo&aacute;n chỉ s&acirc;u khoảng 50 m. Năm 2024, đo&agrave;n mang theo 250 m d&acirc;y chuy&ecirc;n dụng nhưng xuống hết d&acirc;y vẫn chưa chạm đ&aacute;y. Đợt th&aacute;m hiểm năm nay, đo&agrave;n mang gần 500 m d&acirc;y mới c&oacute; thể tiếp cận l&ograve;ng hang sau h&agrave;nh tr&igrave;nh băng rừng 1,5 ng&agrave;y từ trung t&acirc;m x&atilde;.</p>\r\n<figure class=\"tplCaption action_thumb_added\" data-size=\"true\">\r\n<div class=\"fig-picture el_valid\" data-width=\"680\" data-src=\"https://i1-dulich.vnecdn.net/2026/04/27/hang-cha-nghe-o-1777269513-3496-1777269597.jpg?w=0&amp;h=0&amp;q=100&amp;dpr=2&amp;fit=crop&amp;s=21P2Xsq4E6efH8t4OJ-L1w\" data-sub-html=\"&lt;div class=&quot;ss-wrapper&quot;&gt;&lt;div class=&quot;ss-content&quot;&gt;\r\n&lt;p class=&quot;Image&quot;&gt;Th&aacute;c nước b&ecirc;n trong hang Chả Ngh&eacute;o. Ảnh: &lt;em&gt;Oxalis&lt;/em&gt;&lt;/p&gt;\r\n&lt;/div&gt;&lt;/div&gt;\"><picture><source srcset=\"https://i1-dulich.vnecdn.net/2026/04/27/hang-cha-nghe-o-1777269513-3496-1777269597.jpg?w=680&amp;h=0&amp;q=100&amp;dpr=1&amp;fit=crop&amp;s=_P_kVihGUjvnOdK5uzqvfQ 1x, https://i1-dulich.vnecdn.net/2026/04/27/hang-cha-nghe-o-1777269513-3496-1777269597.jpg?w=1020&amp;h=0&amp;q=100&amp;dpr=1&amp;fit=crop&amp;s=RHtJOkk8_0X0-6PbfHEqRg 1.5x, https://i1-dulich.vnecdn.net/2026/04/27/hang-cha-nghe-o-1777269513-3496-1777269597.jpg?w=680&amp;h=0&amp;q=100&amp;dpr=2&amp;fit=crop&amp;s=VkAHks5Xz6-RMFwQcCtf0g 2x\" data-srcset=\"https://i1-dulich.vnecdn.net/2026/04/27/hang-cha-nghe-o-1777269513-3496-1777269597.jpg?w=680&amp;h=0&amp;q=100&amp;dpr=1&amp;fit=crop&amp;s=_P_kVihGUjvnOdK5uzqvfQ 1x, https://i1-dulich.vnecdn.net/2026/04/27/hang-cha-nghe-o-1777269513-3496-1777269597.jpg?w=1020&amp;h=0&amp;q=100&amp;dpr=1&amp;fit=crop&amp;s=RHtJOkk8_0X0-6PbfHEqRg 1.5x, https://i1-dulich.vnecdn.net/2026/04/27/hang-cha-nghe-o-1777269513-3496-1777269597.jpg?w=680&amp;h=0&amp;q=100&amp;dpr=2&amp;fit=crop&amp;s=VkAHks5Xz6-RMFwQcCtf0g 2x\"><img class=\"lazy lazied\" src=\"https://i1-dulich.vnecdn.net/2026/04/27/hang-cha-nghe-o-1777269513-3496-1777269597.jpg?w=680&amp;h=0&amp;q=100&amp;dpr=1&amp;fit=crop&amp;s=_P_kVihGUjvnOdK5uzqvfQ\" alt=\"Th&aacute;c nước b&ecirc;n trong hang Chả Ngh&eacute;o. Ảnh: Oxalis\" loading=\"lazy\" data-src=\"https://i1-dulich.vnecdn.net/2026/04/27/hang-cha-nghe-o-1777269513-3496-1777269597.jpg?w=680&amp;h=0&amp;q=100&amp;dpr=1&amp;fit=crop&amp;s=_P_kVihGUjvnOdK5uzqvfQ\" data-ll-status=\"loaded\"></picture></div>\r\n<figcaption>\r\n<p class=\"Image\" style=\"text-align: center;\">Th&aacute;c nước b&ecirc;n trong hang Chả Ngh&eacute;o. Ảnh:&nbsp;<em>Oxalis</em></p>\r\n</figcaption>\r\n</figure>\r\n<p class=\"Normal\">Theo anh Đại, Chả Ngh&eacute;o nguy hiểm do t&igrave;nh trạng đ&aacute; mẻ v&agrave; đ&aacute; mồ c&ocirc;i thường xuy&ecirc;n rơi tự do từ v&aacute;ch hố sụt xuống đ&aacute;y. V&agrave;o đợt th&aacute;m hiểm năm 2024, khoảng 15h, một chuy&ecirc;n gia th&aacute;m hiểm người Australia đ&atilde; bị đ&aacute; đ&egrave; g&atilde;y tay trong qu&aacute; tr&igrave;nh khảo s&aacute;t hang Chả Ngh&eacute;o.</p>\r\n<p class=\"Normal\">Sau khi sơ cứu v&agrave; kết nối điện thoại vệ tinh về bộ phận điều h&agrave;nh, 17h30, anh Đại y&ecirc;u cầu nh&oacute;m th&aacute;m hiểm di tản ngay lập tức. Sau 6 tiếng băng rừng trong đ&ecirc;m v&agrave; 3 giờ chạy xe, đo&agrave;n đưa nạn nh&acirc;n đến bệnh viện tại Đồng Hới l&uacute;c 3h. Kết quả chụp X-quang x&aacute;c nhận nạn nh&acirc;n chấn thương nghi&ecirc;m trọng.</p>\r\n<p class=\"Normal\">B&ecirc;n cạnh rủi ro địa chất, hệ thống th&aacute;c nước dội trực tiếp v&agrave;o hố sụt cũng l&agrave; th&aacute;ch thức lớn. Anh Đại cho biết, việc lắp d&acirc;y dọc theo đường nước chảy kh&ocirc;ng đảm bảo an to&agrave;n do d&acirc;y bị trơn v&agrave; người th&aacute;m hiểm dễ bị cảm lạnh nếu tiếp x&uacute;c với nước qu&aacute; l&acirc;u. V&igrave; vậy, đo&agrave;n quyết định lắp đường d&acirc;y đi ngang qua v&aacute;ch hang kh&ocirc; ph&iacute;a đối diện th&aacute;c nước nhằm hạn chế tiếp x&uacute;c với nước ở mức tối thiểu.</p>\r\n<p class=\"Normal\">Anh Đại cho biết một số porter địa phương b&agrave;y tỏ mong muốn xuống th&aacute;m hiểm hang, đo&agrave;n khảo s&aacute;t đ&atilde; từ chối để đảm bảo an to&agrave;n.</p>\r\n<p class=\"Normal\">\"Nếu người leo n&uacute;i kh&ocirc;ng nắm vững kỹ thuật đi d&acirc;y l&ecirc;n v&agrave; xuống, khi xảy ra sự cố, c&ocirc;ng t&aacute;c cứu hộ sẽ rất kh&oacute; khăn\", anh Đại n&oacute;i.</p>\r\n<p class=\"Normal\">Theo &ocirc;ng Howard Limbert, tại đoạn hang ngang d&agrave;i 600 m dưới đ&aacute;y hang Chả Ngh&eacute;p, đo&agrave;n đ&atilde; ph&aacute;t hiện một d&ograve;ng s&ocirc;ng ngầm nhưng buộc phải dừng lại v&agrave; l&ecirc;n kế hoạch quay lại v&agrave;o năm sau để tiếp tục kh&aacute;m ph&aacute;.</p>\r\n<p class=\"Normal\">Vị trưởng đo&agrave;n BCRA cũng nhấn mạnh sự qu&yacute; hiếm của Chả Ngh&eacute;o. Tại Việt Nam, việc t&igrave;m thấy một hố sụt thẳng đứng s&acirc;u k&egrave;m th&aacute;c nước như vậy l&agrave; rất hiếm. Đa số hang động ở Quảng B&igrave;nh l&agrave; hang ngang, trong khi dạng hang đứng n&agrave;y thường chỉ thấy ở H&agrave; Giang hay Sơn La.</p>\r\n<p class=\"Normal\">\"N&oacute; rất th&uacute; vị cho c&aacute;c nh&agrave; th&aacute;m hiểm, nhưng v&ocirc; gi&aacute; trị với du kh&aacute;ch v&igrave; qu&aacute; rủi ro\", &ocirc;ng Limbert n&oacute;i.</p>\r\n<div>\r\n<figure class=\"item_slide_show clearfix\">\r\n<div id=\"video_parent_444899\" class=\" layout_version_2    box_embed_video_parent embed_video_new\" data-vorientation=\"portrait\" data-vcate=\"1003834\" data-vscate=\"1003400\" data-vscaten=\"Du lịch\" data-vid=\"444899\" data-ratio=\"2\" data-articleoriginal=\"5067534\" data-ads=\"0\" data-license=\"0\" data-duration=\"11\" data-brandsafe=\"0\" data-type=\"0\" data-play=\"1\" data-frame=\"\" data-aot=\"\" data-videoclassify=\"None\" data-vwidth=\"720\" data-vheight=\"1280\" data-initdom=\"1\" data-view=\"inview\" data-auto=\"1\" data-status=\"play\">\r\n<div id=\"embed_video_444899\" class=\"box_embed_video\">\r\n<div class=\"bg_overlay_small_unpin\">&nbsp;</div>\r\n<div class=\"bg_overlay_small\">&nbsp;</div>\r\n<div class=\"embed-container ratio-custom orientation-portrait\">\r\n<div id=\"video-444899\">\r\n<div id=\"parser_player_444899\" class=\"media_content\">\r\n<div id=\"videoContainter_444899\" class=\"videoContainter\">\r\n<div id=\"media-video-444899\" class=\"video-js vjs-default-skin vjs-controls-enabled vjs-workinghover vjs-v7 media-video-444899-dimensions vjs-playing vjs-has-started vjs-user-inactive\" lang=\"vi\" role=\"region\" data-subtitle=\"0\" data-mode=\"240|360|480|720\" aria-label=\"Video Player\">\r\n<div class=\"vjs-control-bar\" dir=\"ltr\">\r\n<div class=\"vjs-progress-control vjs-control\">\r\n<div class=\"vjs-progress-holder vjs-slider vjs-slider-horizontal\" tabindex=\"0\" role=\"slider\" aria-valuenow=\"67.77\" aria-valuemin=\"0\" aria-valuemax=\"100\" aria-label=\"Progress Bar\" aria-valuetext=\"0:07 of 0:11\">&nbsp;</div>\r\n</div>\r\n</div>\r\n<div class=\"share-hover\">&nbsp;</div>\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n<figcaption class=\"desc_cation\">\r\n<div class=\"inner_caption\">\r\n<p class=\"Image\">L&ograve;ng hang Chả Ngh&eacute;o. Video:&nbsp;<em>BCRA</em></p>\r\n</div>\r\n</figcaption>\r\n</figure>\r\n</div>\r\n<p class=\"Normal\">Trong đợt khảo s&aacute;t 26 hang động lần n&agrave;y, ngo&agrave;i Chả Ngh&eacute;o, c&aacute;c chuy&ecirc;n gia x&aacute;c định c&oacute; hai địa điểm sở hữu gi&aacute; trị khai th&aacute;c du lịch cao nhờ vị tr&iacute; gần trung t&acirc;m Phong Nha v&agrave; khả năng tiếp cận thuận tiện l&agrave; hang Tối Kh&ocirc; v&agrave; một nh&aacute;nh mới của hang Ti&ecirc;n Sơn.</p>\r\n<p class=\"Normal\">Từ năm 1990 đến nay, định kỳ v&agrave;o th&aacute;ng 3 hoặc đầu th&aacute;ng 4 hằng năm, đo&agrave;n th&aacute;m hiểm BCRA d&agrave;nh khoảng hơn một th&aacute;ng để khảo s&aacute;t c&aacute;c hang động mới dựa tr&ecirc;n th&ocirc;ng tin cung cấp từ người d&acirc;n địa phương. Anh Phạm Hồng Đại cho biết, c&ocirc;ng việc n&agrave;y sẽ tiếp tục được triển khai v&agrave;o năm sau khi c&oacute; những manh mối mới về c&aacute;c hệ thống hang chưa được kh&aacute;m ph&aacute;.</p>\r\n<figure class=\"tplCaption action_thumb_added\" data-size=\"true\">\r\n<div class=\"action_thumb flexbox\">&nbsp;</div>\r\n<div class=\"fig-picture el_valid\" data-width=\"680\" data-src=\"https://i1-dulich.vnecdn.net/2026/04/27/ANH-1-1777040202-1777269442-3405-1777269598.webp?w=0&amp;h=0&amp;q=100&amp;dpr=2&amp;fit=crop&amp;s=zThBNXK4seZotLP3qZHgGA\" data-sub-html=\"&lt;div class=&quot;ss-wrapper&quot;&gt;&lt;div class=&quot;ss-content&quot;&gt;\r\n&lt;p class=&quot;Image&quot;&gt;Thạch nhũ trong hang Thi&ecirc;n Cung, nằm gần hang Tối. Ảnh: &lt;em&gt;Oxalis&lt;/em&gt;&lt;/p&gt;\r\n&lt;/div&gt;&lt;/div&gt;\"><picture><source srcset=\"https://i1-dulich.vnecdn.net/2026/04/27/ANH-1-1777040202-1777269442-3405-1777269598.webp?w=680&amp;h=0&amp;q=100&amp;dpr=1&amp;fit=crop&amp;s=lMnixJSjMlrGixcYL2C9QQ 1x, https://i1-dulich.vnecdn.net/2026/04/27/ANH-1-1777040202-1777269442-3405-1777269598.webp?w=1020&amp;h=0&amp;q=100&amp;dpr=1&amp;fit=crop&amp;s=RudIHemkaAM5Lw3D8xRIOQ 1.5x, https://i1-dulich.vnecdn.net/2026/04/27/ANH-1-1777040202-1777269442-3405-1777269598.webp?w=680&amp;h=0&amp;q=100&amp;dpr=2&amp;fit=crop&amp;s=U-CucTV-KX4wcqoYCPjFpA 2x\" data-srcset=\"https://i1-dulich.vnecdn.net/2026/04/27/ANH-1-1777040202-1777269442-3405-1777269598.webp?w=680&amp;h=0&amp;q=100&amp;dpr=1&amp;fit=crop&amp;s=lMnixJSjMlrGixcYL2C9QQ 1x, https://i1-dulich.vnecdn.net/2026/04/27/ANH-1-1777040202-1777269442-3405-1777269598.webp?w=1020&amp;h=0&amp;q=100&amp;dpr=1&amp;fit=crop&amp;s=RudIHemkaAM5Lw3D8xRIOQ 1.5x, https://i1-dulich.vnecdn.net/2026/04/27/ANH-1-1777040202-1777269442-3405-1777269598.webp?w=680&amp;h=0&amp;q=100&amp;dpr=2&amp;fit=crop&amp;s=U-CucTV-KX4wcqoYCPjFpA 2x\"><img class=\"lazy lazied\" src=\"https://i1-dulich.vnecdn.net/2026/04/27/ANH-1-1777040202-1777269442-3405-1777269598.webp?w=680&amp;h=0&amp;q=100&amp;dpr=1&amp;fit=crop&amp;s=lMnixJSjMlrGixcYL2C9QQ\" alt=\"Thạch nhũ trong hang Thi&ecirc;n Cung, nằm gần hang Tối. Ảnh: Oxalis\" loading=\"lazy\" data-src=\"https://i1-dulich.vnecdn.net/2026/04/27/ANH-1-1777040202-1777269442-3405-1777269598.webp?w=680&amp;h=0&amp;q=100&amp;dpr=1&amp;fit=crop&amp;s=lMnixJSjMlrGixcYL2C9QQ\" data-ll-status=\"loaded\"></picture></div>\r\n<figcaption>\r\n<p class=\"Image\" style=\"text-align: center;\">Thạch nhũ trong hang Thi&ecirc;n Cung, nằm gần hang Tối. Ảnh:&nbsp;<em>Oxalis</em></p>\r\n</figcaption>\r\n</figure>\r\n</article>', '1777462198_69f1ebb6d8774.png', 2, 'published', '2026-04-29 11:11:04', '2026-04-29 11:29:58');
INSERT INTO `articles` (`id`, `category_id`, `author_id`, `title`, `slug`, `summary`, `content`, `image`, `views`, `status`, `created_at`, `updated_at`) VALUES
(15, 7, 1, 'Người đàn ông chế xe tải hút đinh, vá lốp \'0 đồng\'', 'ng-i-n-ng-ch-xe-t-i-h-t-inh-v-l-p-0-ng', 'Từng suýt mất mạng vì xe cán phải đinh, lao vào dải phân cách, ông Nguyễn Đức Quân chế bộ nam châm treo dưới gầm xe, hàng ngày chạy trên đường để hút vật nhọn.', '<p class=\"description\">Từng su&yacute;t mất mạng v&igrave; xe c&aacute;n phải đinh, lao v&agrave;o dải ph&acirc;n c&aacute;ch, &ocirc;ng Nguyễn Đức Qu&acirc;n chế bộ nam ch&acirc;m treo dưới gầm xe, h&agrave;ng ng&agrave;y chạy tr&ecirc;n đường để h&uacute;t vật nhọn.</p>\r\n<article id=\"fck_detail_gallery\" class=\"fck_detail \">\r\n<p class=\"Normal\">Giữa trưa ng&agrave;y cuối th&aacute;ng 4, &ocirc;ng Qu&acirc;n gặp một thanh ni&ecirc;n dắt xe m&aacute;y tr&ecirc;n đoạn đường vắng qua khu c&ocirc;ng nghiệp thuộc huyện Đức H&ograve;a, Long An. &Ocirc;ng l&aacute;i xe tải tấp v&agrave;o lề, hỏi thăm. Ch&agrave;ng trai cho biết xe m&aacute;y c&aacute;n phải đinh, xịt lốp. Khu vực n&agrave;y kh&ocirc;ng c&oacute; tiệm sửa n&ecirc;n anh phải đi bộ hơn hai km.</p>\r\n<p class=\"Normal\">Người đ&agrave;n &ocirc;ng 56 tuổi mở th&ugrave;ng xe tải lấy t&uacute;i đồ nghề dụng cụ th&aacute;o b&aacute;nh. X&aacute;c định vết thủng qu&aacute; lớn kh&ocirc;ng thể v&aacute;, &ocirc;ng thay săm mới v&agrave; b&agrave;n giao xe sau 15 ph&uacute;t. Người thanh ni&ecirc;n ngỏ &yacute; gửi tiền nhưng &ocirc;ng Qu&acirc;n từ chối.</p>\r\n<p class=\"Normal\">Hơn một năm qua h&agrave;ng trăm trường hợp tương tự đ&atilde; được &ocirc;ng Nguyễn Đức Qu&acirc;n gi&uacute;p đỡ tr&ecirc;n nhiều tuyến đường của TP HCM.</p>\r\n<figure class=\"tplCaption action_thumb_added\" data-size=\"true\">\r\n<div class=\"fig-picture el_valid\" data-width=\"680\" data-src=\"https://i1-giadinh.vnecdn.net/2026/04/25/Screen-Shot-2026-04-25-at-00-2-8109-4115-1777057347.png?w=0&amp;h=0&amp;q=100&amp;dpr=2&amp;fit=crop&amp;s=2_K3IkjXm5BjTUqZ9YxkbQ\" data-sub-html=\"&lt;div class=&quot;ss-wrapper&quot;&gt;&lt;div class=&quot;ss-content&quot;&gt;\r\n&lt;p class=&quot;Image&quot;&gt;&Ocirc;ng Nguyễn Đức Qu&acirc;n c&ugrave;ng vợ ở phường Dĩ An, TP HCM, trưa 24/4. Ảnh: &lt;em&gt;Ngọc Ng&acirc;n&lt;/em&gt;&lt;/p&gt;\r\n&lt;/div&gt;&lt;/div&gt;\"><picture><source srcset=\"https://i1-giadinh.vnecdn.net/2026/04/25/Screen-Shot-2026-04-25-at-00-2-8109-4115-1777057347.png?w=680&amp;h=0&amp;q=100&amp;dpr=1&amp;fit=crop&amp;s=lT4PK1TGFMGiVZmmOHM1Yw 1x, https://i1-giadinh.vnecdn.net/2026/04/25/Screen-Shot-2026-04-25-at-00-2-8109-4115-1777057347.png?w=1020&amp;h=0&amp;q=100&amp;dpr=1&amp;fit=crop&amp;s=msAYWT2rdIp9haqMIYhO-Q 1.5x, https://i1-giadinh.vnecdn.net/2026/04/25/Screen-Shot-2026-04-25-at-00-2-8109-4115-1777057347.png?w=680&amp;h=0&amp;q=100&amp;dpr=2&amp;fit=crop&amp;s=ecKwyp177k3XEqpmaynvZw 2x\" data-srcset=\"https://i1-giadinh.vnecdn.net/2026/04/25/Screen-Shot-2026-04-25-at-00-2-8109-4115-1777057347.png?w=680&amp;h=0&amp;q=100&amp;dpr=1&amp;fit=crop&amp;s=lT4PK1TGFMGiVZmmOHM1Yw 1x, https://i1-giadinh.vnecdn.net/2026/04/25/Screen-Shot-2026-04-25-at-00-2-8109-4115-1777057347.png?w=1020&amp;h=0&amp;q=100&amp;dpr=1&amp;fit=crop&amp;s=msAYWT2rdIp9haqMIYhO-Q 1.5x, https://i1-giadinh.vnecdn.net/2026/04/25/Screen-Shot-2026-04-25-at-00-2-8109-4115-1777057347.png?w=680&amp;h=0&amp;q=100&amp;dpr=2&amp;fit=crop&amp;s=ecKwyp177k3XEqpmaynvZw 2x\"><img class=\"lazy lazied\" src=\"https://i1-giadinh.vnecdn.net/2026/04/25/Screen-Shot-2026-04-25-at-00-2-8109-4115-1777057347.png?w=680&amp;h=0&amp;q=100&amp;dpr=1&amp;fit=crop&amp;s=lT4PK1TGFMGiVZmmOHM1Yw\" alt=\"Nguyễn Đức Qu&acirc;n\" loading=\"lazy\" data-src=\"https://i1-giadinh.vnecdn.net/2026/04/25/Screen-Shot-2026-04-25-at-00-2-8109-4115-1777057347.png?w=680&amp;h=0&amp;q=100&amp;dpr=1&amp;fit=crop&amp;s=lT4PK1TGFMGiVZmmOHM1Yw\" data-ll-status=\"loaded\"></picture></div>\r\n<figcaption>\r\n<p class=\"Image\">&Ocirc;ng Nguyễn Đức Qu&acirc;n c&ugrave;ng vợ ở phường Dĩ An, TP HCM, trưa 24/4. Ảnh:&nbsp;<em>Ngọc Ng&acirc;n</em></p>\r\n</figcaption>\r\n</figure>\r\n<p class=\"Normal\">Việc l&agrave;m thiện nguyện xuất ph&aacute;t từ một vụ tai nạn của ch&iacute;nh &ocirc;ng. Qu&ecirc; Ph&uacute; Thọ, &ocirc;ng nhập ngũ năm 1988, sau đ&oacute; chuyển v&agrave;o phường Dĩ An, TP HCM lập nghiệp bằng nghề vận tải. Đầu năm 2025, xe tải của &ocirc;ng c&aacute;n phải đinh tại ng&atilde; tư B&igrave;nh Phước (TP Thủ Đức), mất l&aacute;i v&agrave; t&ocirc;ng v&agrave;o dải ph&acirc;n c&aacute;ch.</p>\r\n<p class=\"Normal\">\"Sau lần su&yacute;t mất mạng, t&ocirc;i nghĩ cần l&agrave;m g&igrave; đ&oacute; để kh&ocirc;ng ai gặp nạn giống m&igrave;nh nữa\", &ocirc;ng n&oacute;i.</p>\r\n<p class=\"Normal\">&Ocirc;ng Qu&acirc;n mua nam ch&acirc;m gắn v&agrave;o hai thanh sắt d&agrave;i 1,8 m dưới gầm xe để tự động h&uacute;t c&aacute;c vật sắc nhọn tr&ecirc;n mặt đường mỗi khi xe di chuyển. Tận dụng kinh nghiệm sửa xe m&aacute;y, &ocirc;ng mua th&ecirc;m vỏ v&agrave; ruột xe để thay, v&aacute; miễn ph&iacute; cho người đi đường. Gi&aacute; ruột xe 40.000-45.000 đồng mỗi c&aacute;i với xe m&aacute;y v&agrave; 30.000 đồng với xe đạp. &Ocirc;ng cũng mang theo một can xăng để hỗ trợ người hết xăng, mỗi th&aacute;ng d&agrave;nh hai triệu cho c&aacute;c chi ph&iacute; n&agrave;y.</p>\r\n<p class=\"Normal\">Th&aacute;ng 4/2025, chiếc xe tải 4,5 tấn của gia đ&igrave;nh được d&aacute;n d&ograve;ng chữ \"H&uacute;t đinh từ thiện, v&aacute; vỏ thay ruột Honda miễn ph&iacute;\". Mỗi tuần năm ng&agrave;y, &ocirc;ng chở h&agrave;ng đến c&aacute;c khu c&ocirc;ng nghiệp ở TP HCM, B&igrave;nh Dương, Vũng T&agrave;u, Long An v&agrave; Đồng Nai, kết hợp việc h&uacute;t đinh dọc đường. Mỗi th&aacute;ng, &ocirc;ng thu gom khoảng 30 kg sắt vụn, đinh v&agrave; hỗ trợ h&agrave;ng chục trường hợp hư xe.</p>\r\n<p class=\"Normal\">Thời gian đầu, bạn b&egrave; gọi &ocirc;ng l&agrave; \"Qu&acirc;n kh&ugrave;ng\" v&igrave; l&agrave;m việc kh&ocirc;ng c&ocirc;ng. B&agrave; Phạm Thị V&acirc;n, vợ &ocirc;ng, cho biết ban đầu gia đ&igrave;nh lo lắng khi &ocirc;ng đi sớm về khuya. Nhưng sau v&agrave;i chuyến đi c&ugrave;ng, b&agrave; thay đổi suy nghĩ.</p>\r\n<p class=\"Normal\">B&agrave; kể, trong một lần hai vợ chồng dừng gi&uacute;p một nam thợ hồ bị thủng lốp tr&ecirc;n đường L&ecirc; Thị Ri&ecirc;ng, quận 12 l&uacute;c 22h trong khi điện thoại hết pin, t&uacute;i kh&ocirc;ng c&oacute; tiền. Khi được sửa xong, anh tặng lại vợ chồng &ocirc;ng Qu&acirc;n chai nước ngọt đang cầm tr&ecirc;n tay. \"Khoảnh khắc đ&oacute; khiến ch&uacute;ng t&ocirc;i rất hạnh ph&uacute;c\", b&agrave; n&oacute;i.</p>\r\n<figure class=\"tplCaption action_thumb_added\" data-size=\"true\">\r\n<div class=\"fig-picture el_valid\" data-width=\"680\" data-src=\"https://i1-giadinh.vnecdn.net/2026/04/25/Screen-Shot-2026-04-25-at-00-2-4757-4003-1777057347.png?w=0&amp;h=0&amp;q=100&amp;dpr=2&amp;fit=crop&amp;s=HxAPDEM2r6InIvhGiz-ANg\" data-sub-html=\"&lt;div class=&quot;ss-wrapper&quot;&gt;&lt;div class=&quot;ss-content&quot;&gt;\r\n&lt;p class=&quot;Image&quot;&gt;&Ocirc;ng Nguyễn Đức Qu&acirc;n gỡ đinh, vật sắc nhọn từ hai thanh sắt gắn nam ch&acirc;m dưới gầm xe tải, trưa 24/4. Ảnh: &lt;em&gt;Ngọc Ng&acirc;n&lt;/em&gt;&lt;/p&gt;\r\n&lt;/div&gt;&lt;/div&gt;\"><picture><source srcset=\"https://i1-giadinh.vnecdn.net/2026/04/25/Screen-Shot-2026-04-25-at-00-2-4757-4003-1777057347.png?w=680&amp;h=0&amp;q=100&amp;dpr=1&amp;fit=crop&amp;s=9QFANtowvLEviqzW63BTrg 1x, https://i1-giadinh.vnecdn.net/2026/04/25/Screen-Shot-2026-04-25-at-00-2-4757-4003-1777057347.png?w=1020&amp;h=0&amp;q=100&amp;dpr=1&amp;fit=crop&amp;s=ufwZysh2M9V6rsIH68z9qg 1.5x, https://i1-giadinh.vnecdn.net/2026/04/25/Screen-Shot-2026-04-25-at-00-2-4757-4003-1777057347.png?w=680&amp;h=0&amp;q=100&amp;dpr=2&amp;fit=crop&amp;s=xmTtZnayXYtfprthpeGb8Q 2x\" data-srcset=\"https://i1-giadinh.vnecdn.net/2026/04/25/Screen-Shot-2026-04-25-at-00-2-4757-4003-1777057347.png?w=680&amp;h=0&amp;q=100&amp;dpr=1&amp;fit=crop&amp;s=9QFANtowvLEviqzW63BTrg 1x, https://i1-giadinh.vnecdn.net/2026/04/25/Screen-Shot-2026-04-25-at-00-2-4757-4003-1777057347.png?w=1020&amp;h=0&amp;q=100&amp;dpr=1&amp;fit=crop&amp;s=ufwZysh2M9V6rsIH68z9qg 1.5x, https://i1-giadinh.vnecdn.net/2026/04/25/Screen-Shot-2026-04-25-at-00-2-4757-4003-1777057347.png?w=680&amp;h=0&amp;q=100&amp;dpr=2&amp;fit=crop&amp;s=xmTtZnayXYtfprthpeGb8Q 2x\"><img class=\"lazy lazied\" src=\"https://i1-giadinh.vnecdn.net/2026/04/25/Screen-Shot-2026-04-25-at-00-2-4757-4003-1777057347.png?w=680&amp;h=0&amp;q=100&amp;dpr=1&amp;fit=crop&amp;s=9QFANtowvLEviqzW63BTrg\" alt=\"Nguyễn Đức Qu&acirc;n\" loading=\"lazy\" data-src=\"https://i1-giadinh.vnecdn.net/2026/04/25/Screen-Shot-2026-04-25-at-00-2-4757-4003-1777057347.png?w=680&amp;h=0&amp;q=100&amp;dpr=1&amp;fit=crop&amp;s=9QFANtowvLEviqzW63BTrg\" data-ll-status=\"loaded\"></picture></div>\r\n<figcaption>\r\n<p class=\"Image\">&Ocirc;ng Nguyễn Đức Qu&acirc;n gỡ đinh, vật sắc nhọn từ hai thanh sắt gắn nam ch&acirc;m dưới gầm xe tải, trưa 24/4. Ảnh:&nbsp;<em>Ngọc Ng&acirc;n</em></p>\r\n</figcaption>\r\n</figure>\r\n<p class=\"Normal\">B&agrave; Xu&acirc;n Thu, 70 tuổi, h&agrave;ng x&oacute;m &ocirc;ng Qu&acirc;n thường xuy&ecirc;n thấy vợ chồng &ocirc;ng mang t&uacute;i đồ nghề l&ecirc;n xe từ s&aacute;ng sớm. Chiều về, họ lại mang bao tay đứng b&ecirc;n b&atilde;i đất trống gỡ đinh, mảnh sắt b&aacute;m v&agrave;o nam ch&acirc;m dưới gầm xe. B&agrave; cũng chứng kiến &ocirc;ng Qu&acirc;n nhiều lần gi&uacute;p học sinh trường THCS gần đ&oacute; v&aacute; hoặc thay ruột xe đạp miễn ph&iacute; để c&aacute;c em kịp giờ học.</p>\r\n<p class=\"Normal\">&Ocirc;ng Trần Vụ, Chủ tịch Hội Cựu chiến binh phường Dĩ An, cho biết việc l&agrave;m của &ocirc;ng Qu&acirc;n diễn ra đều đặn, tự nguyện v&agrave; tạo ảnh hưởng t&iacute;ch cực trong khu vực, n&ecirc;n hội đ&atilde; ghi nhận v&agrave; động vi&ecirc;n. Thời điểm dịch Covid-19, &ocirc;ng c&ugrave;ng gia đ&igrave;nh tham gia chở lương thực, nhu yếu phẩm v&agrave;o c&aacute;c điểm phong tỏa.</p>\r\n<p class=\"Normal\">Giữa năm ngo&aacute;i, trong một chuyến chở h&agrave;ng l&uacute;c 20h, &ocirc;ng Qu&acirc;n gặp một thợ h&agrave;n dắt xe m&aacute;y tr&ecirc;n đường vắng. &Ocirc;ng dừng xe v&agrave; ngỏ &yacute; thay săm mới, nhưng người thợ chỉ xin v&aacute; tạm để kịp về nh&agrave; v&agrave; từ chối nhận săm mới, muốn nhường phần đ&oacute; cho người kh&aacute;c cần hơn.</p>\r\n<p class=\"Normal\">\"T&ocirc;i học được nhiều điều từ những người tốt xung quanh v&agrave; tr&acirc;n trọng c&aacute;ch họ biết nghĩ cho người kh&aacute;c\", &ocirc;ng Qu&acirc;n n&oacute;i.</p>\r\n</article>', '1777462218_69f1ebca7f605.png', 1, 'published', '2026-04-29 11:14:14', '2026-04-29 11:30:18');

